function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var left = 48;
  var right = 560;
  var eps = state.eps;
  var xv = state.xval;
  function fmt(v) { return Math.round(v * 100) / 100; }
  var scaleY = (bot - top) / 1.5;
  var thr = 1;
  var ythr = bot - thr * scaleY;
  var i = 0;
  var n = 60;
  var x = 0;
  var y = 0;
  var px = 0;
  var py = 0;
  var clipped = false;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (i = 0; i <= n; i++) {
    x = (i / n) * 4;
    if (x === 0) { y = 0; } else { y = x / Math.sqrt(x * x + eps); }
    px = left + (x / 4) * (right - left);
    py = bot - y * scaleY;
    if (py < top) { py = top; clipped = true; }
    if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
  }
  ctx.stroke();
  if (clipped) { ctx.fillStyle = "#1f4b99"; ctx.font = "12px sans-serif"; ctx.fillText("clipped", 500, top + 16); }
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(left, ythr);
  ctx.lineTo(right, ythr);
  ctx.stroke();
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), left, ythr - 8);
  var ym = 0;
  if (xv === 0) { ym = 0; } else { ym = xv / Math.sqrt(xv * xv + eps); }
  var mx = left + (xv / 4) * (right - left);
  var my = bot - ym * scaleY;
  if (my < top) { my = top; }
  ctx.strokeStyle = "#1f4b99";
  ctx.beginPath();
  ctx.moveTo(mx, bot);
  ctx.lineTo(mx, my);
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(mx, my, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#1f4b99";
  ctx.fillText("y = " + fmt(ym), left, 318);
  ctx.fillText("eps = " + fmt(eps), 300, 318);
  ctx.fillText("toy rms", left, 344);
}
